ResolutionIn{from{opacity:0;transform:translateY(7px) scale(.995)}to{opacity:1;transform:none}}
@media(max-width:900px){.battleResolution{right:66px;bottom:110px;padding:5px 6px}.resolutionWinner{font-size:10px}.resolutionCompare{font-size:7px}.resolutionPlayer{padding:3px 4px}.resolutionScore{font-size:11px}.resolutionCard{padding:1px 3px}}
@media(max-height:470px) and (orientation:landscape){.battleResolution{left:4px;right:60px;bottom:104px;padding:4px 5px}.resolutionCards{gap:2px}.resolutionPlayer{padding:2px 3px}.resolutionPlayerTop b{font-size:8px}}
