@media(prefers-reduced-motion:reduce){.battleResolution{animation:none}}
/* RESULT */
.resultWorld{position:absolute;inset:0 36% 0 0;background:radial-gradient(circle at 46% 42%,rgba(255,210,126,.18),transparent 26%),linear-gradient(145deg,#163b31,#061611)}.resultWorld .grtc-root{position:absolute;inset:7% 8% 2%;display:flex;align-items:flex-end;justify-content:center}.resultWorld .grtc-image{max-height:92%;height:92%;width:auto;object-fit:contain;filter:drop-shadow(0 24px 26px rgba(0,0,0,.42))}.resultRank{position:absolute;left:4%;top:15%;width:30%;z-index:3}.grade{font-size:clamp(100px,15vw,240px);font-weight:1000;line-height:.9}.resultBody{position:absolute;left:39%;right:3%;top:13%;bottom:13%;padding:20px;background:rgba(7,25,21,.9);border:1px solid var(--line);overflow:auto}.rankLine{display:flex;justify-content:space-between;padding:11px;border-bottom:1px solid var(--line);font-weight:900}.resultBtns{position:absolute;right:4%;bottom:4%;display:flex;gap:8px}
