Runtime{position:absolute;inset:4% 6% 16%;display:grid;place-items:center}.profileStage .profileName{position:absolute;left:18px;right:18px;bottom:14px}.profileStats{border:1px solid var(--line);background:rgba(6,20,17,.78);padding:14px;overflow:au

